const payload = typeof $input.item.json.body === 'string'
  ? JSON.parse($input.item.json.body)
  : $input.item.json;

if (!payload.incident_id || !payload.equipment_id) {
  throw new Error('Missing required fields: incident_id or equipment_id');
}

return [{
  json: {
    incident_id: payload.incident_id,
    equipment_id: payload.equipment_id,
    incident_type: payload.incident_type || 'unknown',
    severity: payload.severity || 'low',
    description: payload.description || '',
    reported_at: payload.reported_at || new Date().toISOString(),
    facility_id: payload.facility_id || null,
    reporter_name: payload.reporter_name || 'System'
  }
}];

